customMethods.script:
cellId = BlueRidge.Common.Util.extractQualifiedValues(cellId)
row = BlueRidge.Location.Location.findCellById(self.view.custom.cells, cellId)
if row is None:
	return
self.session.custom.cell = {"locationId": row.get("value"), "code": row.get("code") or "", "name": row.get("name") or ""}

# Bulk open (backlog 3.4). bulkOpenDraft is the authoritative per-cavity
# entry map: the repeater rows are input-only embeds and can only report
# upward via the page-scoped bulkOpenRowChanged message, so nothing is
# ever read back out of the repeater here.
draft = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.bulkOpenDraft) or {}
tool = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.activeTool) or {}
cell = BlueRidge.Common.Util.extractQualifiedValues(self.session.custom.cell) or {}
rows = []
for key in draft.keys():
	d = draft.get(key) or {}
	rows.append({"toolCavityId": d.get("toolCavityId"), "itemId": d.get("itemId"), "scannedLtt": d.get("scannedLtt")})
term = None
try:
	term = self.session.custom.terminal.terminalLocationId
except:
	term = None
res = BlueRidge.Workorder.DieCast.submitBulkOpen(rows, tool.get("ToolId"), cell.get("locationId"), self.session.custom.appUserId, term) or {}
# Per-row outcomes live on the VIEW, not inside the rows: the repeater's
# instances transform overlays them, so they survive the rebuild below.
self.view.custom.bulkOpenResult = res.get("Rows") or {}
if res.get("Rejected"):
	# A batch gate fired -- NOTHING was written, so the operator's entries
	# stay exactly as they are and no rebuild happens.
	BlueRidge.Common.Notify.toast("Nothing opened", res.get("Message") or "", "warning")
	return res
# Partial submission: keep only the rows that did NOT open, so the operator
# re-enters the failures alone and never a cavity that already succeeded.
rowResults = res.get("Rows") or {}
kept = {}
pending = 0
for key in draft.keys():
	if (rowResults.get(key) or {}).get("state") == "ok":
		continue
	d = draft.get(key) or {}
	kept[key] = d
	if d.get("itemId") is not None or ("%s" % (d.get("scannedLtt") or "")).strip() != "":
		pending += 1
self.view.custom.bulkOpenDraft = kept
self.view.custom.bulkOpenPendingCount = pending
level = "success"
if res.get("Failed"):
	level = "warning" if res.get("Opened") else "error"
BlueRidge.Common.Notify.toast("Bulk open", res.get("Message") or "", level)
self.view.custom.refreshToken = (self.view.custom.refreshToken or 0) + 1
# D9: ONE CRT notice per SUBMIT, naming every basket that opened CRT --
# never one dialog per cavity, which trains operators to dismiss dialogs.
# LAST, after the refresh bump: every basket has already committed.
BlueRidge.Common.Ui.crtNotice(res.get("CrtLots"), res.get("Opened"))
return res

# Wipe every operator entry AND the last submission's per-row results, then
# rebuild the rows from the live cavity/open-basket state.
self.view.custom.bulkOpenDraft = {}
self.view.custom.bulkOpenResult = {}
self.view.custom.bulkOpenPendingCount = 0
self.view.custom.refreshToken = (self.view.custom.refreshToken or 0) + 1

rows = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.breakdown) or []
entries = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.breakdownEntries) or {}
tool = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.activeTool) or {}
cell = BlueRidge.Common.Util.extractQualifiedValues(self.session.custom.cell) or {}
lines = []
overflow = []
for r in rows:
	r = r or {}
	if not r.get("IsOpen"):
		continue
	lotId = r.get("LotId")
	e = entries.get("%s" % lotId) or {}
	good = BlueRidge.Common.Util.toIntOrNone(e.get("good"))
	if good is None:
		good = BlueRidge.Common.Util.toIntOrNone(r.get("ProposedGood")) or 0
	scrapLines = []
	for sl in (BlueRidge.Common.Util.extractQualifiedValues(e.get("scrapLines")) or []):
		sl = sl or {}
		d = sl.get("defectCodeId")
		q = BlueRidge.Common.Util.toIntOrNone(sl.get("quantity"))
		if d and q:
			scrapLines.append({"defectCodeId": d, "quantity": q})
	lines.append({"lotId": lotId, "pieceDelta": good, "scrapLines": scrapLines})
	h = BlueRidge.Common.Util.toIntOrNone(r.get("MaxHeadroom"))
	if h is not None and h < 2147483647 and good > h:
		overflow.append({"lotId": lotId, "lotName": r.get("LotName") or "",
			"cavityNumber": r.get("CavityNumber") or "", "toolCavityId": r.get("ToolCavityId"),
			"itemId": r.get("ItemId"), "headroom": h, "good": good,
			"remainder": good - h, "scrapLines": scrapLines})
if not lines:
	BlueRidge.Common.Notify.toast("Nothing to submit", "Compute a breakdown first (enter the shot count and press Compute).", "warning")
	return
term = None
try:
	term = self.session.custom.terminal.terminalLocationId
except:
	term = None
if overflow:
	self.view.custom.pendingSubmit = system.util.jsonEncode({"grossShots": BlueRidge.Common.Util.toIntOrNone(self.view.custom.grossShots), "lines": lines, "overflow": overflow,
		"shiftId": self.view.custom.selectedShiftId, "toolId": tool.get("ToolId"),
		"cellLocationId": cell.get("locationId"), "terminalLocationId": term})
	system.perspective.openPopup("mpp-diecast-overflow",
		"BlueRidge/Components/Popups/DieCastOverflow",
		params={"replyMessage": "dieCastOverflowResult", "popupId": "mpp-diecast-overflow", "overflow": overflow},
		modal=True, showCloseIcon=True)
	return
data = {"shiftId": self.view.custom.selectedShiftId, "toolId": tool.get("ToolId"), "lines": lines, "shotLoss": [], "grossShots": BlueRidge.Common.Util.toIntOrNone(self.view.custom.grossShots), "cellLocationId": cell.get("locationId")}
result = BlueRidge.Workorder.DieCast.recordShiftOutput(data, appUserId=self.session.custom.appUserId, terminalLocationId=term)
BlueRidge.Common.Ui.notifyResult(result, successTitle="Shift output recorded")
if result and result.get("Status"):
	self._afterSubmit()

lotId = self.view.custom.pendingReleaseLotId
if lotId is None:
	return
term = None
try:
	term = self.session.custom.terminal.terminalLocationId
except:
	term = None
data = {
	"lotId": lotId,
	"shiftId": self.view.custom.selectedShiftId,
	"appUserId": self.session.custom.appUserId,
	"terminalLocationId": term,
}
result = BlueRidge.Lots.Lot.releaseDieCast(data)
BlueRidge.Common.Ui.notifyResult(result, successTitle="Basket released")
if result and result.get("Status"):
	self.view.custom.pendingReleaseLotId = None
	self.view.custom.pendingReleaseLotName = ""
	self.view.custom.refreshToken = (self.view.custom.refreshToken or 0) + 1

messageHandlers.script:
entries = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.breakdownEntries) or {}
entries = dict(entries)
entries["%s" % payload.get("lotId")] = {"good": payload.get("good"), "scrapLines": BlueRidge.Common.Util.extractQualifiedValues(payload.get("scrapLines")) or []}
self.view.custom.breakdownEntries = entries

# The only channel a repeater row has back to this view: params are
# input-only, so every keystroke/selection is reported up here and folded
# into the authoritative bulkOpenDraft map (read whole, mutate, write whole).
draft = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.bulkOpenDraft) or {}
draft = dict(draft)
draft["%s" % payload.get("toolCavityId")] = {
	"toolCavityId": payload.get("toolCavityId"),
	"itemId": payload.get("itemId"),
	"scannedLtt": payload.get("scannedLtt") or "",
}
pending = 0
for k in draft.keys():
	d = draft.get(k) or {}
	if d.get("itemId") is not None or ("%s" % (d.get("scannedLtt") or "")).strip() != "":
		pending += 1
self.view.custom.bulkOpenDraft = draft
self.view.custom.bulkOpenPendingCount = pending
